<?php
declare(strict_types=1);
namespace LeenkatForms\Admin;

use LeenkatForms\Files\AttachmentMigration as Migration;
use LeenkatForms\Files\PrivateStorage;
use LeenkatForms\Files\FileRecords;
final class FileSecurityPage {
    public static function hooks(): void {add_action('admin_post_lkf_file_maintenance',[self::class,'action']);}
    private static function gate(): void {if(!current_user_can('manage_options')||!current_user_can('lkf_view_entries'))wp_die(esc_html__('Access denied.','leenkat-forms'),'',['response'=>403]);}
    public static function action(): void {
        // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.MissingUnslash,WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- Values are exact-compared against a closed enum/literal or validated by the existing schema; sanitizing approval flags could turn a malformed value into approval.
        self::gate();check_admin_referer('lkf_file_maintenance');$operation=$_POST['operation'] ?? '';if(!is_string($operation))wp_die(esc_html__('Invalid operation.', 'leenkat-forms'),'',['response'=>400]);
        try{
            if($operation==='plan'){$result=Migration::plan();$run=$result['run_id'];}
            // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.MissingUnslash,WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- Identifier/token is type-checked and validated by the existing digit/hex grammar and ownership/nonce gate before lookup or maintenance; keep exact identity.
            elseif($operation==='copy'||$operation==='finalize'){$run=is_string($_POST['run_id'] ?? null)?$_POST['run_id']:'';if($operation==='finalize'&&($_POST['confirm_remove'] ?? '')!=='1')throw new \RuntimeException(__('Explicit approval to remove legacy public copies is required.', 'leenkat-forms'));Migration::apply($run,$operation==='finalize');}
            // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.MissingUnslash,WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- Identifier/token is type-checked and validated by the existing digit/hex grammar and ownership/nonce gate before lookup or maintenance; keep exact identity.
            elseif($operation==='rollback'){$run=is_string($_POST['run_id'] ?? null)?$_POST['run_id']:'';if(($_POST['confirm_restore'] ?? '')!=='1')throw new \RuntimeException(__('Explicit approval to restore former public files is required.', 'leenkat-forms'));Migration::rollback($run,true);}
            // phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedHooknameFound -- Existing lkf_-prefixed public hook is retained for backward compatibility; no unprefixed hook is introduced.
            elseif($operation==='cleanup'){do_action('lkf_file_maintenance');$run='';}
            else throw new \RuntimeException(__('Invalid file maintenance operation.', 'leenkat-forms'));
            wp_safe_redirect(admin_url('admin.php?page=leenkat-forms-file-security&result=ok'.($run?'&run='.rawurlencode($run):'')));exit;
        }catch(\Throwable $e){wp_die(esc_html($e->getMessage()),'',['response'=>409]);}
    }
    private static function start(string $operation,string $run=''): void {echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="lkf-security-action">';wp_nonce_field('lkf_file_maintenance');echo '<input type="hidden" name="action" value="lkf_file_maintenance"><input type="hidden" name="operation" value="'.esc_attr($operation).'"><input type="hidden" name="run_id" value="'.esc_attr($run).'">';}
    public static function render(): void {
        self::gate();global $wpdb;ManagementPage::start(__('Attachment Security','leenkat-forms'));echo '<div class="lkf-attachment-security"><p class="lkf-security-intro">'.esc_html__('Private form attachments use protected downloads. Files explicitly saved to the WordPress Media Library can remain publicly accessible.','leenkat-forms').'</p>';
        $ready=\LeenkatForms\Files\EncryptedStorage::available();echo '<div class="notice '.($ready?'notice-success':'notice-error').' inline"><p>'.esc_html($ready?__('New private uploads are authenticated and encrypted before they are written to WordPress uploads. Downloading plaintext requires authorization.','leenkat-forms'):__('Private storage is unavailable. New private uploads are blocked until the server configuration is corrected.','leenkat-forms')).'</p></div>';
        // phpcs:ignore WordPress.Security.NonceVerification.Recommended,WordPress.Security.ValidatedSanitizedInput.MissingUnslash,WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- Read-only routing/filter/presentation input; it changes no data, capabilities are enforced by the page and values are allowlisted/escaped before use. Values are exact-compared against a closed enum/literal or validated by the existing schema; sanitizing approval flags could turn a malformed value into approval.
        if(($_GET['result'] ?? '')==='ok')echo '<div class="notice notice-success inline"><p>'.esc_html__('File maintenance completed. Review the migration state below.','leenkat-forms').'</p></div>';
        // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery,WordPress.DB.DirectDatabaseQuery.NoCaching -- Custom plugin tables and transaction control have no equivalent WordPress object API; values are prepared and access is gated by the caller. Fresh custom-table state is required for locking, ownership checks, exports and current admin results; a cache could be stale.
        $inventory=Migration::inventory();$failed=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}lkf_entry_files WHERE status IN ('cleanup_failed','deleting')");echo '<section class="lkf-security-section" aria-labelledby="lkf-inventory-title"><h2 id="lkf-inventory-title">'.esc_html__('Inventory','leenkat-forms').'</h2><table class="widefat striped lkf-list-table lkf-security-inventory"><caption class="screen-reader-text">'.esc_html__('Attachment inventory','leenkat-forms').'</caption><thead><tr><th scope="col">'.esc_html__('Attachment category','leenkat-forms').'</th><th scope="col">'.esc_html__('Count','leenkat-forms').'</th></tr></thead><tbody>';
        foreach([__('Private registered attachments','leenkat-forms')=>$inventory['private_registered'],__('Legacy private attachments with public sources','leenkat-forms')=>$inventory['legacy_private'],__('Legacy Media Library references','leenkat-forms')=>$inventory['media'],__('Missing or invalid legacy references','leenkat-forms')=>$inventory['invalid_or_missing'],__('Other file records requiring review','leenkat-forms')=>$inventory['other_file_records'],__('Pending or failed authorized cleanup','leenkat-forms')=>$failed] as $label=>$count)echo '<tr><th scope="row">'.esc_html($label).'</th><td>'.(int)$count.'</td></tr>';echo '</tbody></table>';
        if($inventory['invalid_or_missing'])echo '<p class="description">'.esc_html__('Missing and invalid references are reported for review. They are never used to read or delete arbitrary filesystem paths.','leenkat-forms').'</p>';echo '</section>';
        echo '<section class="lkf-security-section" aria-labelledby="lkf-migration-title"><h2 id="lkf-migration-title">'.esc_html__('Legacy Attachment Migration','leenkat-forms').'</h2><p>'.esc_html__('Check older uploaded files and create verified backups before moving them to private storage. Public copies are not deleted automatically.','leenkat-forms').'</p><p class="description">'.esc_html__('Copying preserves the public source. Removing verified public copies is a separate approved operation. Media Library files are excluded.','leenkat-forms').'</p>';self::start('plan');echo '<button class="button button-secondary">'.esc_html__('Create Dry Run and Verified Backups','leenkat-forms').'</button></form>';
        // phpcs:ignore WordPress.Security.NonceVerification.Recommended,WordPress.Security.ValidatedSanitizedInput.MissingUnslash,WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- Read-only routing/filter/presentation input; it changes no data, capabilities are enforced by the page and values are allowlisted/escaped before use. Identifier/token is type-checked and validated by the existing digit/hex grammar and ownership/nonce gate before lookup or maintenance; keep exact identity.
        $run=$_GET['run'] ?? get_option('lkf_file_migration_latest','');
        if(is_string($run)&&$run!=='')try{$report=Migration::report(Migration::read($run));echo '<h3>'.esc_html(sprintf(/* translators: %s: migration run identifier. */ __('Migration %s','leenkat-forms'),$run)).'</h3><p>'.esc_html__('Verified file and database backups are stored privately for recovery.','leenkat-forms').'</p><table class="widefat striped lkf-list-table lkf-security-report"><caption class="screen-reader-text">'.esc_html__('Legacy migration file status','leenkat-forms').'</caption><thead><tr><th scope="col">'.esc_html__('Entry','leenkat-forms').'</th><th scope="col">'.esc_html__('Original filename','leenkat-forms').'</th><th scope="col">'.esc_html__('Size','leenkat-forms').'</th><th scope="col">'.esc_html__('State','leenkat-forms').'</th></tr></thead><tbody>';foreach($report['files'] as $file)echo '<tr><td>'.(int)$file['entry_id'].'</td><td>'.esc_html($file['name']).'</td><td>'.(int)$file['bytes'].'</td><td>'.esc_html($file['state'].(!empty($file['message'])?' — '.$file['message']:'')).'</td></tr>';echo '</tbody></table>';
            self::start('copy',$run);echo '<button class="button">'.esc_html__('Copy and Update Private Associations','leenkat-forms').'</button></form>';
            self::start('finalize',$run);echo '<p><label><input type="checkbox" name="confirm_remove" value="1" required> '.esc_html__('I approve removing the legacy public copies after verifying their private destinations and backups.','leenkat-forms').'</label></p><button class="button button-primary">'.esc_html__('Complete Approved Migration','leenkat-forms').'</button></form>';
            self::start('rollback',$run);echo '<p><label><input type="checkbox" name="confirm_restore" value="1" required> '.esc_html__('I approve restoring the former public files and entry references. This can make the former URLs accessible again.','leenkat-forms').'</label></p><button class="button">'.esc_html__('Restore Verified Backup','leenkat-forms').'</button></form>';
        }catch(\Throwable){echo '<p>'.esc_html__('Migration information is unavailable. Create a new dry run or consult the private recovery backup.','leenkat-forms').'</p>';}
        echo '</section><section class="lkf-security-section" aria-labelledby="lkf-cleanup-title"><h2 id="lkf-cleanup-title">'.esc_html__('Authorized Cleanup','leenkat-forms').'</h2><p>'.esc_html__('Review and retry file cleanup operations that could not be completed. Files required by active downloads or pending email deliveries remain protected.','leenkat-forms').'</p><p class="description">'.esc_html__('Trash and restore preserve attachments. Permanent deletion waits for active downloads and deliveries, cancels pending deliveries safely, and records cleanup failures for retry.','leenkat-forms').'</p>';self::start('cleanup');echo '<button class="button">'.esc_html__('Retry Authorized Cleanup','leenkat-forms').'</button></form></section><p class="description">'.esc_html__('Office document structure is checked with the ZIP reader bundled with WordPress. A missing file-info or private-storage capability causes validation to fail closed.','leenkat-forms').'</p></div>';ManagementPage::end();
    }
}
